// ─── File: LedgerDemo.java ───
// Double-entry ledger: zero-sum, append-only, idempotent, derived balances, reversing correction.
// Each class below would be its own file in a real project.
package com.bank.ledger;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class LedgerDemo {

    private static final Logger log = Logger.getLogger("Ledger");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LedgerService ledger = new LedgerService();

        // Balanced transfer: debit Rajesh -50000, credit Priya +50000 → sums to zero.
        ledger.post("PAY-1001", "rent transfer", List.of(
                new Entry("SAV2001", new BigDecimal("-50000"), "INR"),
                new Entry("CUR3001", new BigDecimal("50000"),  "INR")));

        // Duplicate business key → rejected by unique constraint (idempotency).
        ledger.post("PAY-1001", "rent transfer (retry)", List.of(
                new Entry("SAV2001", new BigDecimal("-50000"), "INR"),
                new Entry("CUR3001", new BigDecimal("50000"),  "INR")));

        // Unbalanced transaction → rejected by the zero-sum trigger (money cannot be created).
        ledger.post("BAD-1", "creates money", List.of(
                new Entry("CUR3001", new BigDecimal("99999"), "INR")));

        // Derived balances by summing immutable entries (never a stored mutable column).
        log.info(() -> "Rajesh balance (derived) = " + ledger.balance("SAV2001"));
        log.info(() -> "Priya balance (derived)  = " + ledger.balance("CUR3001"));

        // Correction: a mistake is fixed by a REVERSING transaction, never an edit/delete.
        ledger.post("REV-1001", "reverse PAY-1001", List.of(
                new Entry("SAV2001", new BigDecimal("50000"),  "INR"),
                new Entry("CUR3001", new BigDecimal("-50000"), "INR")));
        log.info(() -> "After reversal, Rajesh = " + ledger.balance("SAV2001")
                + ", Priya = " + ledger.balance("CUR3001"));
    }
}

// ─── model/Entry.java ───
class Entry {
    final String accountId; final BigDecimal amount; final String currency;
    Entry(String accountId, BigDecimal amount, String currency) {
        this.accountId = accountId; this.amount = amount; this.currency = currency;
    }
}

// ─── model/LedgerTransaction.java ───
class LedgerTransaction {
    final String businessKey, description; final List<Entry> entries;
    LedgerTransaction(String businessKey, String description, List<Entry> entries) {
        this.businessKey = businessKey; this.description = description; this.entries = entries;
    }
}

// ─── service/LedgerService.java ───
// Mirrors the DB rules in-memory for the demo; the DB is the real guardian.
class LedgerService {
    private static final Logger log = Logger.getLogger("Ledger");
    private final List<LedgerTransaction> committed = new ArrayList<>();      // append-only
    private final Set<String> businessKeys = new HashSet<>();                 // unique key

    void post(String businessKey, String description, List<Entry> entries) {
        // NOT-NULL + non-zero checks (DB enforces these too)
        for (Entry e : entries) {
            if (e.accountId == null || e.amount == null || e.currency == null)
                throw new IllegalArgumentException("account/amount/currency must be NOT NULL");
            if (e.amount.signum() == 0) throw new IllegalArgumentException("zero entry not allowed");
        }
        // IDEMPOTENCY: unique business key (DB unique index enforces this)
        if (!businessKeys.add(businessKey)) {
            log.warning(() -> "duplicate business key " + businessKey + " → rejected (idempotent)");
            return;
        }
        // ZERO-SUM: entries must net to zero (DB deferred constraint trigger enforces this)
        BigDecimal sum = entries.stream().map(e -> e.amount).reduce(BigDecimal.ZERO, BigDecimal::add);
        if (sum.signum() != 0) {
            businessKeys.remove(businessKey);
            log.severe(() -> "REJECTED " + businessKey + ": entries sum to " + sum + " ≠ 0 (money cannot be created)");
            return;
        }
        committed.add(new LedgerTransaction(businessKey, description, entries));  // atomic append
        log.info(() -> "POSTED " + businessKey + " (" + description + ") balanced, entries=" + entries.size());
    }

    // BALANCE is DERIVED by summing immutable entries — never a mutable stored column.
    BigDecimal balance(String accountId) {
        return committed.stream()
                .flatMap(t -> t.entries.stream())
                .filter(e -> e.accountId.equals(accountId))
                .map(e -> e.amount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
